.bar-chart{display:flex;flex-direction:column;gap:8px;font-family:sans-serif;font-size:14px}
.bar-row{display:grid;grid-template-columns:140px 1fr 70px;align-items:center;gap:10px}
.bar-row .name{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.bar-row .track{background:#eef1f5;border-radius:6px;height:14px;overflow:hidden}
.bar-row .fill{height:100%;border-radius:6px}
.bar-row .val{text-align:right;font-variant-numeric:tabular-nums;font-weight:600}
&lt;/style&gt;
&lt;div class="bar-chart"&gt;
${(() =&gt; {
  const max = Math.max(...data.map(r =&gt; r[1])) || 1;
  return data.map(r =&gt; {
    const w = (r[1] / max * 100).toFixed(1);
    return html`&lt;div class="bar-row"&gt;
      &lt;span class="name" title="${r[0]}"&gt;${r[0]}&lt;/span&gt;
      &lt;div class="track"&gt;&lt;div class="fill" style="width:${w}%;background:linear-gradient(90deg,#e0413f,#D8232A)"&gt;&lt;/div&gt;&lt;/div&gt;
      &lt;span class="val"&gt;${r[1].toLocaleString("es-CO")}&lt;/span&gt;
    &lt;/div&gt;`;
  });
})()}
&lt;/div&gt;`

Mapa Interactivo de Colombia en Observable

topojson = window.topojson

// ── Datos: un solo archivo TopoJSON (3.4 MB vs 153 MB en GeoJSON) ─────────
topo = FileAttachment("data/colombia_moderate.topojson").json()

dept = topojson.feature(topo, topo.objects.departamentos)
mun  = topojson.feature(topo, topo.objects.municipios)

// ── Listas derivadas ──────────────────────────────────────────────────────
nombres_deptos = ["— Colombia (todos) —",
  ...new Set(dept.features.map(f =&gt; f.properties.departamento).sort())
]





































viewof depto_sel = Inputs.select(nombres_deptos, {
  label: "📍 Departamento",
  value: "— Colombia (todos) —"
})







dept_filtrado = depto_sel === "— Colombia (todos) —"
  ? dept
  : ({
      type: "FeatureCollection",
      features: dept.features.filter(
        f =&gt; f.properties.departamento === depto_sel
      )
    })

mun_filtrado = depto_sel === "— Colombia (todos) —"
  ? null
  : ({
      type: "FeatureCollection",
      features: mun.features.filter(
        f =&gt; f.properties.departamento === depto_sel
      )
    })

n_municipios = mun_filtrado ? mun_filtrado.features.length : null























// ── Paleta de colores para municipios ─────────────────────────────────────
color_mun = mun_filtrado
  ? d3.scaleOrdinal()
      .domain(mun_filtrado.features.map(f =&gt; f.properties.municipio))
      .range(d3.quantize(d3.interpolate("#fde68a", "#b45309"),
                         Math.max(mun_filtrado.features.length, 2)))
  : null







// ══════════════════════════════════════════════════════════════════════════
//  MAPA D3
// ══════════════════════════════════════════════════════════════════════════
{
  const width  = 860
  const height = 680

  // ── Contenedor principal ───────────────────────────────────────────────
  const container = d3.create("div")
    .style("position", "relative")
    .style("font-family", "system-ui, sans-serif")

  // ── SVG ────────────────────────────────────────────────────────────────
  const svg = container.append("svg")
    .attr("width",   "100%")
    .attr("viewBox", `0 0 ${width} ${height}`)
    .style("background", "#f0f4f8")
    .style("border-radius", "12px")

  // ── Proyección: ajustar al feature visible ────────────────────────────
  const geo_base = depto_sel === "— Colombia (todos) —" ? dept : dept_filtrado

  const projection = d3.geoMercator()
    .fitExtent([[20, 20], [width - 20, height - 60]], geo_base)

  const path = d3.geoPath().projection(projection)

  // ── Grupo: departamentos base (fondo gris suave) ──────────────────────
  svg.append("g")
    .selectAll("path")
    .data(dept.features)
    .join("path")
      .attr("d", path)
      .attr("fill",   "#e8ddc4")
      .attr("stroke", "#b8a98a")
      .attr("stroke-width", 0.5)

  // ── Grupo: municipios (si hay departamento seleccionado) ──────────────
  if (mun_filtrado) {
    svg.append("g")
      .selectAll("path")
      .data(mun_filtrado.features)
      .join("path")
        .attr("d", path)
        .attr("fill",   d =&gt; color_mun(d.properties.municipio))
        .attr("fill-opacity", 0.7)
        .attr("stroke", "#92400e")
        .attr("stroke-width", 0.7)
      .append("title")
        .text(d =&gt; d.properties.municipio)
  }

  // ── Etiquetas de municipios (solo si el polígono tiene área suficiente) ──
  if (mun_filtrado) {
    const MIN_AREA = 400
    svg.append("g")
      .attr("pointer-events", "none")
      .selectAll("text")
      .data(mun_filtrado.features.filter(d =&gt; {
        const bounds = path.bounds(d)
        const w = bounds[1][0] - bounds[0][0]
        const h = bounds[1][1] - bounds[0][1]
        return w * h &gt; MIN_AREA
      }))
      .join("text")
        .attr("x", d =&gt; path.centroid(d)[0])
        .attr("y", d =&gt; path.centroid(d)[1])
        .attr("text-anchor", "middle")
        .attr("dominant-baseline", "middle")
        .attr("font-size", "9px")
        .attr("font-family", "system-ui, sans-serif")
        .attr("font-weight", "600")
        .attr("fill", "#3b1f07")
        .attr("paint-order", "stroke")
        .attr("stroke", "white")
        .attr("stroke-width", "2.5px")
        .attr("stroke-linejoin", "round")
        .text(d =&gt; d.properties.municipio)
  }

  // ── Grupo: contorno del departamento seleccionado ─────────────────────
  if (depto_sel !== "— Colombia (todos) —") {
    svg.append("g")
      .selectAll("path")
      .data(dept_filtrado.features)
      .join("path")
        .attr("d", path)
        .attr("fill",         "none")
        .attr("stroke",       "#c0392b")
        .attr("stroke-width", 2.5)
  }

  // ── Tooltips con etiquetas de departamentos ───────────────────────────
  if (depto_sel === "— Colombia (todos) —") {
    const tooltip = container.append("div")
      .style("position",       "absolute")
      .style("pointer-events", "none")
      .style("background",     "rgba(26,60,94,0.9)")
      .style("color",          "white")
      .style("padding",        "5px 10px")
      .style("border-radius",  "6px")
      .style("font-size",      "12px")
      .style("font-weight",    "600")
      .style("display",        "none")

    svg.selectAll("path")
      .on("mouseover", function(event, d) {
        d3.select(this).attr("fill", "#b5975a").attr("fill-opacity", 0.85)
        tooltip
          .style("display", "block")
          .text(d.properties?.departamento || "")
      })
      .on("mousemove", function(event) {
        const [mx, my] = d3.pointer(event, container.node())
        tooltip
          .style("left", (mx + 12) + "px")
          .style("top",  (my - 28) + "px")
      })
      .on("mouseout", function() {
        d3.select(this)
          .attr("fill", "#e8ddc4")
          .attr("fill-opacity", 1)
        tooltip.style("display", "none")
      })
  } else {
    // Tooltips para municipios
    const tooltip = container.append("div")
      .style("position",       "absolute")
      .style("pointer-events", "none")
      .style("background",     "rgba(26,60,94,0.9)")
      .style("color",          "white")
      .style("padding",        "5px 10px")
      .style("border-radius",  "6px")
      .style("font-size",      "12px")
      .style("display",        "none")

    svg.selectAll("g:nth-child(2) path")
      .on("mouseover", function(event, d) {
        d3.select(this).attr("fill-opacity", 1).attr("stroke-width", 2)
        tooltip
          .style("display", "block")
          .html(`&lt;b&gt;${d.properties.municipio}&lt;/b&gt;&lt;br&gt;
                 &lt;span style="font-size:10px;opacity:.8"&gt;${d.properties.departamento}&lt;/span&gt;`)
      })
      .on("mousemove", function(event) {
        const [mx, my] = d3.pointer(event, container.node())
        tooltip
          .style("left", (mx + 12) + "px")
          .style("top",  (my - 40) + "px")
      })
      .on("mouseout", function(event, d) {
        d3.select(this)
          .attr("fill-opacity", 0.7)
          .attr("stroke-width", 0.7)
        tooltip.style("display", "none")
      })
  }

  // ── Barra de información inferior ────────────────────────────────────
  const info_y = height - 35
  const infobar = svg.append("g")

  infobar.append("rect")
    .attr("x", 0).attr("y", info_y - 10)
    .attr("width", width).attr("height", 50)
    .attr("fill", "rgba(26,60,94,0.75)")

  const info_text = depto_sel === "— Colombia (todos) —"
    ? `Colombia · 33 departamentos · 1119 municipios · Fuente: IGAC / GADM v4.1`
    : `${depto_sel} · ${n_municipios} municipio(s) · Fuente: IGAC / GADM v4.1`

  infobar.append("text")
    .attr("x", width / 2).attr("y", info_y + 12)
    .attr("text-anchor", "middle")
    .attr("fill", "white")
    .attr("font-size", "11px")
    .text(info_text)

  return container.node()
}








Nota metodológica: Los datos cartográficos corresponden a la división político-administrativa oficial de Colombia según el Instituto Geográfico Agustín Codazzi — IGAC y el Marco Geoestadístico Nacional del DANE, descargados mediante la base de datos geoespacial GADM v4.1.

1.5 El efecto encuestadora
Comparando cada encuesta con la tendencia agregada se estiman los sesgos de cada casa. Recuerda que en la simulación pusimos un sesgo de +2, −2, 0 y +1 puntos a favor de A en Alfa, Beta, Gamma y Delta. ¿Lo recuperamos?

encuestas_largo |&gt;
  filter(candidato == "A") |&gt;
  left_join(agregado |&gt; filter(candidato == "A") |&gt; select(dia, esperado = fit), by = "dia") |&gt;
  mutate(desvio = prop - esperado) |&gt;
  group_by(casa) |&gt;
  summarise(encuestas = n(), sesgo_estimado_pts = round(mean(desvio) * 100, 1),
            ee_pts = round(sd(desvio) / sqrt(n()) * 100, 1))

# A tibble: 4 × 4
  casa  encuestas sesgo_estimado_pts ee_pts
  &lt;chr&gt;     &lt;int&gt;              &lt;dbl&gt;  &lt;dbl&gt;
1 Alfa         21                0.9    0.3
2 Beta          7               -2.4    0.6
3 Delta        18                0.4    0.3
4 Gamma        14               -0.9    0.4


Los sesgos estimados (+0,9; −2,4; +0,4 y −0,9 puntos) recuperan el orden general (Beta está claramente por debajo de las demás) pero no los valores exactos (+2, −2, +1 y 0). Hay dos razones: la tendencia agregada se calculó con las mismas encuestas sesgadas, de modo que absorbe parte del sesgo, y lo que se estima es la desviación respecto al consenso de las casas, no respecto a la verdad (que en la práctica se desconoce hasta la elección).






TipConsejo



Con pocas encuestas por casa (Beta tiene solo 7), los sesgos estimados son ruidosos. Un enfoque más completo modela el sesgo de cada casa como un efecto aleatorio en un modelo mixto (Módulo 6), que reparte la incertidumbre de forma coherente.

